534→            console.error('[ZipCodeChecker] API returned error:', data.error, '| API_BASE="' + API_BASE + '" SHOP="' + SHOP + '"');
535→            res.innerHTML = '<div class="zcc-result fail"><div class="zcc-result-icon">' + ICONS.xCircle + '</div><div class="zcc-result-content"><div class="zcc-result-message">Something went wrong. Please try again.</div></div></div>';
536→            try {
537→              sessionStorage.removeItem('zcc:valid');
538→              sessionStorage.removeItem('zcc:zip');
