725→  function joinWaitlist(zip, email, name, wBtn) {
726→    wBtn.disabled = true;
727→    var wBtnIcon = wBtn.querySelector('.zcc-wl-btn-icon');
728→    var wBtnLabel = wBtn.querySelector('.zcc-wl-btn-label');
729→    if (wBtnIcon) wBtnIcon.innerHTML = ICONS.spinner;
730→    if (wBtnLabel) wBtnLabel.textContent = 'Submitting\u2026';
731→    if (!wBtnIcon && !wBtnLabel) wBtn.textContent = 'Submitting\u2026';
732→
733→    var payload = { shop: SHOP, zip: zip, email: email };
734→    if (name) payload.name = name;
735→
736→    fetch(API_BASE + "/api/waitlist", {
737→      method: "POST",
738→      headers: { "Content-Type": "application/json" },
739→      body: JSON.stringify(payload),
740→    })
741→      .then(function (r) { return r.json(); })
742→      .then(function (data) {
743→        var wlEl = wBtn.closest(".zcc-wl");
744→        if (data.success) {
745→          if (wlEl) wlEl.innerHTML =
746→            '<div class="zcc-wl-success">' +
747→            '<span class="zcc-wl-success-icon">' + ICONS.checkmark + '</span>' +
748→            '<span>Your request has been submitted! We\u2019ll notify you when delivery is available.</span>' +
749→            '</div>';
