 139→        showSocialProof: formData.get("showSocialProof") === "true",
 140→        borderRadius: String(formData.get("borderRadius") || "8"),
 141→        customCss: String(formData.get("customCss") || "") || null,
 142→      };
 143→
 144→      // Server-side plan gating: strip premium fields the shop's plan doesn't allow
 145→      const subscription = await getShopSubscription(shop);
 146→      const limits = PLAN_LIMITS[subscription.planTier];
 147→      if (!limits.customCss) {
 148→        data.customCss = null;
 149→      }
 150→      if (!limits.cartBlocking) {
 151→        data.blockCartOnInvalid = false;
 152→        data.blockCheckoutInCart = false;
 153→      }
 154→
 155→      await db.widgetConfig.upsert({
 156→        where: { shop },
 157→        create: { shop, ...data },
 158→        update: data,
 159→      });
 160→
 161→      await syncConfigMetafield(admin, data);
 162→
 163→      return { success: true };
 164→    }
 165→
 166→    if (intent === "reset") {
 167→      const resetData = {
 168→        position: "inline",
 169→        primaryColor: "#008060",
 170→        successColor: "#008060",
 171→        errorColor: "#D72C0D",
 172→        backgroundColor: "#FFFFFF",
 173→        textColor: "#202223",
 174→        heading: "Check Delivery Availability",
 175→        placeholder: "Enter your zip code",
 176→        buttonText: "Check",
 177→        successMessage: "Great news! We deliver to your area.",
 178→        errorMessage: "Sorry, we don't deliver to this area yet.",
 179→        notFoundMessage: "We currently do not ship to this ZIP code.",
 180→        showEta: true,
 181→        showZone: false,
 182→        showWaitlistOnFailure: false,
 183→        showCod: true,
 184→        showReturnPolicy: true,
 185→        showCutoffTime: true,
 186→        showDeliveryDays: true,
 187→        blockCartOnInvalid: false,
 188→        blockCheckoutInCart: false,
 189→        showSocialProof: true,
 190→        borderRadius: "8",
 191→        customCss: null,
 192→      };
 193→
 194→      await db.widgetConfig.upsert({
 195→        where: { shop },
 196→        create: { shop },
 197→        update: resetData,
 198→      });
 199→
 200→      await syncConfigMetafield(admin, resetData);
 201→
 202→      return { success: true, action: "reset" };
 203→    }
