1751→                            transition: "background 0.15s ease",
1752→                            flexShrink: 0,
1753→                          }} />
1754→                          {s.label}
1755→                        </button>
1756→                      ))}
1757→                    </div>
1758→
1759→                    {/* Plan enforcement notice — shown when Free plan strips colors */}
1760→                    {!limits.widgetFullCustom && (
1761→                      <Banner tone="warning">
1762→                        <Text as="p" variant="bodySm">
1763→                          This preview shows how the widget will look on your storefront. Custom colors require a Starter plan or above — the widget uses default colors until you upgrade.{" "}
