1765→                        </Text>
1766→                      </Banner>
1767→                    )}
1768→
1769→                    {/* Preview widget — device frame + dot-grid */}
1770→                    <div style={{
1771→                      border: "1px solid #e2e8f0",
1772→                      borderRadius: 12,
1773→                      overflow: "hidden",
1774→                      background: "#fff",
1775→                    }}>
1776→                      {/* Browser chrome */}
1777→                      <div style={{
1778→                        height: 32,
1779→                        background: "#f8fafc",
1780→                        borderBottom: "1px solid #e2e8f0",
1781→                        display: "flex",
1782→                        alignItems: "center",
1783→                        padding: "0 12px",
1784→                        gap: 6,
1785→                      }}>
1786→                        <div style={{ width: 8, height: 8, borderRadius: "50%", background: "#ff5f57" }} />
1787→                        <div style={{ width: 8, height: 8, borderRadius: "50%", background: "#febc2e" }} />
1788→                        <div style={{ width: 8, height: 8, borderRadius: "50%", background: "#28c840" }} />
1789→                      </div>
1790→                      {/* Dot-grid preview area */}
1791→                      <div style={{
1792→                        padding: 20,
1793→                        background: "radial-gradient(circle, #e2e8f0 1px, transparent 1px)",
1794→                        backgroundSize: "20px 20px",
1795→                        backgroundColor: "#f8fafc",
1796→                      }}>
1797→                        <WidgetPreview cfg={previewCfg} previewState={previewState} widgetFullCustom={limits.widgetFullCustom} />
1798→                      </div>
1799→                    </div>
1800→                  </BlockStack>
1801→                </Card>
1802→              </div>
1803→            </InlineGrid>
1804→          </Layout.Section>
1805→        </Layout>
1806→      </Box>
1807→      {/* Reset Confirmation Modal */}
1808→      <Modal
1809→        open={resetModalOpen}
1810→        onClose={() => setResetModalOpen(false)}
1811→        title="Reset to default settings?"
1812→        primaryAction={{
1813→          content: "Reset to Defaults",
1814→          onAction: handleResetConfirm,
1815→          destructive: true,
1816→        }}
1817→        secondaryActions={[
1818→          {
1819→            content: "Cancel",
1820→            onAction: () => setResetModalOpen(false),
1821→          },
1822→        ]}
1823→      >
1824→        <Modal.Section>
1825→          <Text as="p" variant="bodyMd">
1826→            This will erase all your current widget customizations (colors,
1827→            messages, toggles, custom CSS) and restore the original default
1828→            settings. This action cannot be undone.
1829→          </Text>
1830→        </Modal.Section>
1831→      </Modal>
1832→    </Page>
1833→  );
1834→}
